// Pure-removal face test, BEFORE any 6-edge repair. Each retained four-neighbor set
// must meet every original blue seven not containing the proposed face vertex.
use std::io::{self,BufRead};
fn blue(a:&[u32;27],mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros() as usize;p&=p-1;if blue(a,p&!a[i],k-1){return true}}false}
fn four(a:&[u32;27],p:u32,v:usize,keep:u32,opts:u32,k:u32)->bool{if k==0{return !blue(a,p&!(1<<v)&!keep,7)}let mut b=opts;while b.count_ones()>=k{let x=b&b.wrapping_neg();b^=x;if four(a,p,v,keep|x,b,k-1){return true}}false}
fn main(){let mut hist=[[0u64;27];27];let mut ex=false;for l in io::stdin().lock().lines(){let l=l.unwrap();let (id,g)=l.split_once(' ').unwrap();let b=g.as_bytes();let mut a=[0u32;27];let mut ec=0;let mut t=0;for j in 0..27{for i in 0..j{if (b[1+t/6]-63)>>(5-t%6)&1==1{a[i]|=1<<j;a[j]|=1<<i;ec+=1}t+=1}}for z in 0..27{if ec-a[z].count_ones()!=82{continue}let p=((1<<27)-1)^(1<<z);let mut lock=[0u32;27];for i in 0..27{if i==z{continue}let mut e=a[i]&p&((1<<i)-1);while e!=0{let j=e.trailing_zeros() as usize;e&=e-1;if blue(&a,p&!a[i]&!a[j]&!(1<<i)&!(1<<j),6){lock[i]|=1<<j;lock[j]|=1<<i}}}let(mut n,mut m)=(0,0);let mut faces=vec![];for v in 0..27{if v==z{continue}let k=lock[v].count_ones();if k<=4&&(a[v]&p).count_ones()>=4{n+=1;if four(&a,p,v,lock[v],a[v]&p&!lock[v],4-k){m+=1;faces.push(v)}}}hist[n][m]+=1;if !ex&&n>=6&&m<6{eprintln!("{} {} {} {} {:?}",id,z,n,m,faces);ex=true}}}for n in 0..27{for m in 0..27{if hist[n][m]>0{println!("{} {} {}",n,m,hist[n][m])}}}}
